import React, {
  forwardRef,
  useEffect,
  useImperativeHandle,
  useRef,
  useState,
} from 'react';

import { useValueNavigation } from './hooks/useValueNavigation.js';
import type { _TextSpinButtonProps, _TextSpinButtonRef } from './types.js';
import { useSelection } from '../hooks/useSelection.js';
import { spinButtonStyle } from '../SpinButton.sty.js';

/**
 * @internal
 * Use the _TextSpinButton component to pick a text from a list of given text values.
 */
export const _TextSpinButton = /* @__PURE__ */ forwardRef<
  _TextSpinButtonRef,
  _TextSpinButtonProps
>((props, forwardedRef) => {
  const {
    placeholder,
    disabled = false,
    readonly = false,
    values,
    required = false,
  } = props;

  const rootRef = useRef<HTMLSpanElement>(null);
  const { getSelection, setSelection, selectAll, deselectAll } =
    useSelection(rootRef);

  const [error, setError] = useState(false);

  const { value, keyDownHandler, searchValue, clearValue } =
    useValueNavigation(props);

  // provide root element reference and utitily
  useImperativeHandle(
    forwardedRef,
    () => {
      return {
        type: 'text' as const,
        element: rootRef,
        setSelection,
        getSelection,
        selectAll,
        deselectAll,
        searchValue,
        clearValue,
      };
    },
    [
      clearValue,
      deselectAll,
      getSelection,
      searchValue,
      selectAll,
      setSelection,
    ],
  );

  useEffect(() => {
    if (!rootRef.current) {
      return;
    }
    rootRef.current.textContent = value ?? '';
    document.activeElement === rootRef.current && selectAll();
    // no need to trigger on selectAll update, only trigger on value change
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [value]);

  // set errorstate on value change
  useEffect(() => {
    if (required && value === null) {
      setError(true);
    } else {
      setError(value !== null && !values.includes(value));
    }
  }, [required, value, values]);

  return (
    <span
      contentEditable={!disabled && !readonly}
      ref={rootRef}
      tabIndex={0}
      role="spinbutton"
      spellCheck={false}
      className={spinButtonStyle({ disabled, error })}
      style={
        {
          '--data-placeholder': `"${placeholder}"`,
        } as React.CSSProperties
      }
      aria-disabled={disabled}
      onKeyDown={keyDownHandler}
      onFocus={() => {
        selectAll();
        rootRef.current?.scrollIntoView({
          block: 'nearest',
          inline: 'nearest',
        });
      }}
      onBlur={deselectAll}
      onBeforeInput={(e) => e.preventDefault()}
      onPaste={(e) => e.preventDefault()}
      onDrop={(e) => e.preventDefault()}
      onCut={(e) => e.preventDefault()}
      aria-label={placeholder}
    />
  );
});

(
  _TextSpinButton as typeof _TextSpinButton & { displayName: string }
).displayName = '_TextSpinButton';
